return {clues={
-- T0001
{id="t0001-01",kind="set",pieces={"Badge","Map"},where={{place="police",spot="mailbox",lean="containment",rival="agricultural"}},title="badge and map",body="The photo and name are completely scratched off the badge. The map shows quarantine zones with routes crossed out in red. I count six tallies on the binding tape, only four crossed through."},
{id="t0001-02",kind="set",pieces={"Bucket","WaterBottle"},where={{place="police",spot="mailbox",lean="agricultural",rival="containment"}},title="bucket and water bottle",body="Bucket in the mailbox with a water bottle. Tag says 'Site 12 - Compound B'. Same numbers on the spray schedule I found at the feed store. They were tracking something in the fields."},
-- T0002
{id="t0002-01",kind="set",pieces={"FirstAidKit","Bandage"},where={{place="hospital",spot="corpse",lean="containment",rival="agricultural",outfit="medical"}},title="First aid kit and bandage",body="The first aid kit is still sealed. A clean bandage is folded around its handle. A patient wrist label is tied through it, with no name on it."},
{id="t0002-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="hospital",spot="corpse",lean="agricultural",rival="containment",outfit="medical"}},title="Notebook and water bottle",body="Notebook shows spray schedules for the crops. Water bottle beside it has yellowish residue. Last entry reads: 'livestock refusing the new feed.'"},
-- T0003
{id="t0003-01",kind="set",pieces={"DuctTape","GardeningSprayEmpty"},where={{place="farm",spot="furniture",lean="containment",rival="agricultural"}},title="Duct tape and garden sprayer",body="Seed husks cling to the duct tape. The empty garden sprayer has bleach marks on it. Both are tied in one bundle, with road mud on them."},
{id="t0003-02",kind="set",pieces={"SeedBag","HandShovel"},where={{place="farm",spot="furniture",lean="agricultural",rival="containment"}},title="Seed bag and hand shovel",body="The seed bag is folded shut around the shovel handle. A straight line of dark soil runs from the blade to the bag's seam. The shovel's grip has no soil on it."},
-- T0004
{id="t0004-01",kind="set",pieces={"Map","Lunchbox"},where={{place="checkpoint",spot="vehicle",lean="containment",rival="agricultural"}},title="Map and lunchbox",body="The lunchbox is wedged under the fold of the map. The route line passes the checkpoint and stops. A spoon is laid across the road home."},
{id="t0004-02",kind="set",pieces={"Bucket","Fertilizer"},where={{place="checkpoint",spot="vehicle",lean="agricultural",rival="containment"}},title="Bucket and fertilizer",body="Pale granules cling inside the rim of the bucket. The fertilizer sack beside it is dry and carefully folded. Its open corner is tucked under the seat."},
-- T0005
{id="t0005-01",kind="set",pieces={"Briefcase","Screwdriver"},where={{place="office",spot="furniture",lean="containment",rival="agricultural"}},title="Briefcase and screwdriver",body="The screwdriver is inside the open briefcase. The lock is intact, but the keyhole's metal is bright from turning. A loose key sits in the lining."},
{id="t0005-02",kind="set",pieces={"SeedBag","Fertilizer"},where={{place="office",spot="furniture",lean="agricultural",rival="containment"}},title="Seed bag and fertilizer",body="A seed packet is tucked into the stitched fold of the fertilizer sack. The planting diagram is intact. The panel for mixing instructions has been cut out cleanly."},
-- T0006
{id="t0006-01",kind="set",pieces={"Map","Postcard"},where={{place="bookstore",spot="mailbox",lean="containment",rival="agricultural"}},title="Map and postcard",body="The postcard is stamped and addressed. The map under it ends at a street crossed out in pencil. The message stops at, “We were told to wait by—”."},
{id="t0006-02",kind="set",pieces={"Newspaper","Notebook"},where={{place="bookstore",spot="mailbox",lean="agricultural",rival="containment"}},title="Newspaper and notebook",body="The newspaper reports widespread crop failure. The notebook inside tracks field spraying schedules, the last entry reading: 'animals won't touch the feed.'"},
-- T0007
{id="t0007-01",kind="set",pieces={"Whistle","FirstAidKit"},where={{place="transmission",spot="vehicle",lean="containment",rival="agricultural"}},title="Whistle and first aid kit",body="The whistle and first aid kit are sealed together, never opened. Soot darkens the bundle. The clean outlines suggest it was packed before the fire."},
{id="t0007-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="transmission",spot="vehicle",lean="agricultural",rival="containment"}},title="notebook and water bottle",body="The notebook tracks spray schedules for the back forty. The water bottle still has residue at the bottom. Last entry: 'Livestock won't touch the feed.'"},
-- T0008
{id="t0008-01",kind="set",pieces={"Rope","WaterBottle"},where={{place="warehouse",spot="furniture",lean="containment",rival="agricultural"}},title="Rope and water bottle",body="The evacuation tag on the rope has its name scratched out. The bottle's label is peeled off; the same number is inked on the cap. Both are tied with one cord."},
{id="t0008-02",kind="set",pieces={"Bucket","Notebook"},where={{place="warehouse",spot="furniture",lean="agricultural",rival="containment"}},title="Bucket and notebook",body="The notebook is lying across the bucket. Page labels: “control — standing” and “trial spray — curled by noon.” It adds, “mix still active after valve shut.”"},
-- T0009
{id="t0009-01",kind="set",pieces={"Newspaper","RubberBand"},where={{place="government",spot="furniture",lean="containment",rival="agricultural"}},title="Newspaper and rubber band",body="A rubber band holds the newspaper open. Its fold covers the correction column, and the headline still shows. The page has split along the correction's first sentence."},
{id="t0009-02",kind="set",pieces={"GardeningSprayEmpty","Notebook"},where={{place="government",spot="furniture",lean="agricultural",rival="containment"}},title="Garden sprayer and notebook",body="The empty garden sprayer left a clean circle on the notebook. A dried green line runs from the nozzle to a sketch of crop rows."},
-- T0010
{id="t0010-01",kind="written",pieces={"idcard"},where={{place="farm",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},person="person-a",title="ID card",body="Field plots: weekly soil checks. Road access may close at short notice. Reverse: “Keep the old mare in the dry stall tonight.”"},
{id="t0010-02",kind="set",pieces={"Map","HandShovel"},where={{place="farm",spot="corpse",lean="agricultural",rival="containment",outfit="farm"}},person="person-a",title="Map and hand shovel",body="The crop row on the map is circled twice: “second pass, same mix.” Soil fills the shovel socket. The blade is stained blue-green from the treated rows."},
-- T0011
{id="t0011-01",kind="written",pieces={"idcard"},where={{place="office",spot="mailbox",lean="containment",rival="agricultural"}},person="person-b",title="ID card",body="Delivery: office to road crews. Return copy expected when access resumes. Reverse: “Please bring the chipped blue cup back; it was my sister's.”"},
{id="t0011-02",kind="set",pieces={"Twine","HandTorch"},where={{place="office",spot="mailbox",lean="containment",rival="agricultural"}},person="person-b",title="Twine and hand torch",body="The baling twine and hand torch both smell sharply of bleach. Mud outlines between them show a third object was removed."},
-- T0012
{id="t0012-01",kind="written",pieces={"businesscard"},where={{place="checkpoint",spot="vehicle",lean="containment",rival="agricultural"}},person="person-c",title="Business card",body="Transfer window: after road access ends. Return copy to sender. Reverse: “Bread for Mother, no crust if it is still warm.”"},
{id="t0012-02",kind="set",pieces={"Crayons","AnimalFeedBag"},where={{place="checkpoint",spot="vehicle",lean="agricultural",rival="containment"}},person="person-c",title="Crayons and animal feed bag",body="Yellow fertilizer crystals fill the seam between crayons and sack. The crystals are damp beneath a dry outer layer."},
-- T0013
{id="t0013-01",kind="set",pieces={"UmbrellaBlack","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Black umbrella and camera",body="The black umbrella has a treated-seed stain on it. The camera carries a closure mark. One rope knot holds the two together.",anchor={map="IrvingtonStashMap1",mark=1}},
{id="t0013-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook and water bottle",body="A clear ring has dried across the notebook's crop-row drawing. The bottle cap is clean. The page is stained only where the drawn rows meet.",anchor={map="IrvingtonStashMap1",note=1}},
{id="t0013-03",kind="written",pieces={"dispatch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Dispatch slip",body="“Track access ends at the barrier. Keep the west lane clear for the last vehicle.” The receiving line is blank; on the back, someone asks for a green scarf to be saved.\n\nThe person who handed this to me asked me to keep the date. I did, though the next version left that day out entirely.\n\nThe next morning I looked for a second copy and found only the envelope. I left this one unfolded for whoever came after us.",anchor={map="IrvingtonStashMap1",note=2}},
{id="t0013-04",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="The note lists three crop rows and a water check across both sides. A phone number is written below the last line.\n\nThe paper felt damp when I picked it up from the desk. The mark on my thumb did not come off when I washed my hands.\n\nI kept it because the number might still work. The stain spread to my other fingers by morning.",anchor={map="IrvingtonStashMap1",note=3}},
-- T0014
{id="t0014-01",kind="set",pieces={"Screwdriver","RubberBand"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Screwdriver and rubber band",body="A rubber band holds a seed-treatment slip to the screwdriver. The groove beside the wheel sketch is packed with green powder. It looks like the dust on treated seed, and the handle smells of it.",anchor={print="AmericanTire"}},
{id="t0014-02",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Receipt",body="The receipt charges four tires to the county road crew, but lists only three serial numbers. Beside the blank fourth line, someone wrote “keep off public return until clearance review.” Reverse: “Save the smoothest for the child's bicycle.”\n\nI asked for the old page back after the new instructions arrived. They said it had been destroyed, but its corner was still in my pocket.\n\nThe person who was supposed to collect it had no time to stop. I did not put it back with the rest of the ordinary papers.",anchor={print="AmericanTire"}},
-- T0015
{id="t0015-01",kind="set",pieces={"Crowbar","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Crowbar and briefcase",body="The crowbar and briefcase are wrapped in a child's raincoat. One stayed dry, but the other was left in road mud.",anchor={map="EkronStashMap8",mark=1}},
{id="t0015-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Torn Note",body="\"Do not use the new mixture. The ratio was wrong.\"\nI found this near the pump house. The signature is mud-smeared.\nThat evening, the fields went quiet.",anchor={map="EkronStashMap8",mark=1}},
-- T0016
{id="t0016-01",kind="set",pieces={"PipeWrench","Map"},where={{place="transmission",spot="vehicle",lean="containment",rival="agricultural"}},title="Pipe wrench and map",body="A broken barrier board crushed the pipe wrench against the road map. Clean undersides: both were here before the road was blocked.",anchor={scene="RVSPlonkies"}},
{id="t0016-02",kind="set",pieces={"SeedBag","Fertilizer"},where={{place="farm",spot="vehicle",lean="agricultural",rival="containment"}},title="Seed bag and fertilizer",body="The seed sack is wedged against the fertilizer bag in the van. Its stitched mouth is green at one corner. The fertilizer label is clean where a thumb would lift it.",anchor={scene="RVSPlonkies"}},
-- T0017
{id="t0017-01",kind="set",pieces={"FirstAidKit","Bandage"},where={{place="police",spot="furniture",lean="containment",rival="agricultural"}},title="First aid kit and bandage",body="The first aid kit is sealed and pushed behind a rat-chewed board. A bandage is set on top, dry and neatly folded. It looks like someone expected to come back for it.",anchor={scene="RDSRatKing"}},
{id="t0017-02",kind="set",pieces={"GardeningSprayEmpty","Notebook"},where={{place="farm",spot="furniture",lean="agricultural",rival="containment"}},title="Garden sprayer and notebook",body="The empty sprayer is tacky around its trigger. A notebook page has dried against its side. The page shows a rat-chewed root beside three crop rows.",anchor={scene="RDSRatKing"}},
-- T0018
{id="t0018-01",kind="set",pieces={"Wrench","WalkieTalkie1"},where={{place="office",spot="furniture",lean="containment",rival="agricultural"}},title="Wrench and walkie-talkie",body="Three pickup dots mark the open wrench and the hand radio. Two were scratched away, with no wear around them.",anchor={scene="RBJackieJaye",version="A"}},
{id="t0018-02",kind="set",pieces={"Notebook","WaterBottle"},where={{place="office",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook and water bottle",body="The notebook is trapped under a glass desk cover. Its crop-row sketch has a water stain across the center. The bottle beside it is dry and capped.",anchor={scene="RBJackieJaye",version="B"}},
-- T0020
{id="t0020-01",kind="set",pieces={"TirePump","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Tire pump and first aid kit",body="The tire pump is tied to the first aid kit by a clipped lanyard. An empty loop shows where an identifying tag was cut off.",anchor={map="BBurgStashMap1",mark=1}},
{id="t0020-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Letter",body="Please keep the lesson room windows shut until the spray crew has finished the field across the road. The children can smell it from the front room, and the paint on the porch rail has gone dull since the new mix went on the corn.\n\nTheir mother has paid for the whole week already.",anchor={map="BBurgStashMap1",mark=1}},
-- T0021
{id="t0021-01",kind="set",pieces={"Jack","Clipboard"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Jack and clipboard",body="The car jack and clipboard have the same black paint on them. A fresh scrape shows an older evacuation color underneath.",anchor={map="LouisvilleStashMap1",mark=1}},
{id="t0021-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Letter",body="The test-plot sample jars lost their labels in the rain. Don't put pesticide samples in the rifle-cleaning tin again; the household still keeps its loose screws there.\n\nThe seed-treatment crew left the plot half sprayed and the rows beside it have gone yellow. I scrubbed the tin twice and it still smells sweet.\n\nI stayed until dark in case the crew came back for the jars. No one did.",anchor={map="LouisvilleStashMap1",mark=1}},
-- T0022
{id="t0022-01",kind="set",pieces={"LugWrench","HandTorch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Lug wrench and hand torch",body="Road dust coats the lug wrench and the hand torch. Their ties are clean and newly cut. I think the bundle was repacked after travel.",anchor={map="MarchRidgeStashMap1",mark=1}},
{id="t0022-02",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Keep the pesticide trial jars sealed until the spray plot is dry. The neighbor's calves got into the treated rows and have not eaten since; the dog is still in the yard.\n\nI kept one copy for myself. The trial crew promised to come for the other jars and never did.\n\nThe label on the lid is the only part of that week I trusted.",anchor={map="MarchRidgeStashMap1",mark=1}},
-- T0023
{id="t0023-01",kind="set",pieces={"RadioReceiver","Battery","Screwdriver"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Radio receiver, battery and screwdriver",body="The radio receiver's open with the screwdriver beside it. Battery was pulled when the alert supposedly went out. Dispatch log says this unit confirmed the warning. Someone wrote what they needed to see.",anchor={print="CircuitalHealing"}},
{id="t0023-02",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="The field trial's receiver came back marked 'no fault found,' though it stopped transmitting at the plot. The owner asked to hold the invoice until after harvest; the bench still wants payment.\n\nThe plot beside it was sprayed twice that week and the rows nearest the receiver wilted first. I wrote the dates here while I could still remember them.\n\nThe bench could not say whether the spray or the receiver failed first.",anchor={print="CircuitalHealing"}},
-- T0024
{id="t0024-01",kind="set",pieces={"SpeedingTicket","BeerBottle","Pencil"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Speeding ticket, beer bottle and pencil",body="The speeding ticket's dated after they shut down access. I see pencil marks changing the time. The beer bottle's still sealed, dropped at the gate.",anchor={print="IrvingtonSpeedway"}},
{id="t0024-02",kind="written",pieces={"memo"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Spray Log",body="Applied the trial batch to the corn field just before sunrise. The sweet smell lingered past noon and the solution stayed wet. By evening my neighbor called to say his chickens were dead.",anchor={print="IrvingtonSpeedway"}},
-- T0027
{id="t0027-01",kind="set",pieces={"Tarp","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Tarp and bath towel",body="The folded tarp and bath towel are wedged under unused warning tape. Footprints pass around the bundle rather than toward it.",anchor={map="BBurgStashMap2",mark=1}},
{id="t0027-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Letter",body="The caretaker says the grounds crew borrowed the kitchen sink for a rinse. Please keep the side room locked until the treated beds are dry; the folding chairs are still needed tomorrow.\n\nThe beds along the wall were sprayed that morning and the leaves already curl. I kept this page with the garden receipts, not the ordinary papers.",anchor={map="BBurgStashMap2",mark=1}},
-- T0028
{id="t0028-01",kind="set",pieces={"EmptyJar","Pencil","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Empty jar, pencil and paper",body="The jar has a green film inside. The paper lists produce codes and rinse requirements. Someone used the pencil to mark off crates, then stopped halfway.",anchor={map="BBurgStashMap3",mark=1}},
{id="t0028-02",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Receipt",body="The repair ticket orders the front doors welded shut at the checkpoint, but the locksmith billed for cutting off the back lock. A guard stood at the gap and turned away every family with a child.\n\nThe order had no name on it, only a stamp. I kept the scrap because the same stamp followed us from the previous stop. The first entry was crossed out; I have not tried to improve it.",anchor={map="BBurgStashMap3",mark=1}},
-- T0029
{id="t0029-01",kind="set",pieces={"GardenHoe","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="garden hoe and camera",body="Four notches on the hoe, four on the camera. A fifth is filed down on both. Bound with roadblock tape. Last frame: empty checkpoint.",anchor={map="BBurgStashMap4",mark=1}},
{id="t0029-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Letter",body="I marked the water barrel too, after the field crew sprayed the rows upwind. They call the rinse routine; I still will not let the dog drink until the tank is flushed.\n\nThe barrel water had a green skin on it by morning and the beans nearest the spray went limp. I wrote the time before I went back for the others.",anchor={map="BBurgStashMap4",mark=1}},
-- T0030
{id="t0030-01",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Do not sell the catch until the county finishes its water check. They called it routine, but the fish order is still in the icebox and the supplier wants payment.\n\nThe pond below the sprayed field had gone cloudy and the fish were up at the surface. I meant to ask about the runoff in the morning, but the farm crew had already left, and this was all that remained.",anchor={map="BBurgStashMap5",mark=1}},
{id="t0030-02",kind="set",pieces={"EmptySandbag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Empty sandbag and water bottle",body="I found an empty sandbag with a faded unit number. The water bottle next to it has an unbroken quarantine seal. Someone knotted them together with the same cord.",anchor={map="BBurgStashMap5",mark=1}},
-- T0031
{id="t0031-01",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Letter",body="I left the spare key where you asked. The bus went past the property, but the office says our address was never on its pickup list. I thought you would come back for me.\n\nMy mother put it with the household bills so it would not be thrown away. It was the only part of the week that still had a date.\n\nSomeone had to finish the household list even though the office had closed. I wrote the names in the space left for expenses.",anchor={map="BBurgStashMap6",mark=1}},
{id="t0031-02",kind="set",pieces={"Notebook","Pencil","Teacup"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook, pencil and teacup",body="A notebook and pencil lie by a teacup with sweet residue. The notebook holds spray-plot rows for test day. A note asks that the sample page stay out of the household drawer.",anchor={map="BBurgStashMap6",mark=1}},
-- T0032
{id="t0032-01",kind="set",pieces={"DishCloth","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Dish cloth and map",body="The dish cloth and road map are tied with cut warning tape. Six tally cuts mark the dish cloth, but only four are crossed through.",anchor={map="BBurgStashMap7",mark=1}},
{id="t0032-02",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Leave the canisters outside the fence until the grounds crew finishes the spray test. The gate was already locked when the delivery arrived; the return form charges us for the missing seal.\n\nThe grass along the fence went brown in stripes by the next day. Every canister carried a trial label, and the crew had no one left to ask.",anchor={map="BBurgStashMap7",mark=1}},
-- T0033
{id="t0033-01",kind="set",pieces={"PaperclipBox","WalkieTalkie1"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Paperclip box and walkie-talkie",body="Opposite route arrows are painted on the paperclip box and radio. The older arrow was scraped away beneath fresh road grit.",anchor={map="BBurgStashMap8",mark=1}},
{id="t0033-02",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Farm Note",body="The new spray made the room reek for days. Mom's throat is raw. The hens stopped laying after the field run. The seedlings in the test plot all withered.",anchor={map="BBurgStashMap8",mark=1}},
-- T0034
{id="t0034-01",kind="set",pieces={"Screwdriver","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Screwdriver and paper",body="A screwdriver and paper lie here. The sheet tracks pesticide runs, same field three times overnight. No crop needs that much treatment.",anchor={map="EkronStashMap1",mark=1}},
-- T0035
{id="t0035-01",kind="set",pieces={"Potato","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Potato and notebook",body="This potato has a checkpoint tag from three days after lockdown. The notebook shows guard duty logs, names all scratched out. He logged vehicles through, then disappeared.",anchor={map="EkronStashMap2",mark=1}},
-- T0036
{id="t0036-01",kind="set",pieces={"Bag_ALICEpack","Fertilizer"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Backpack and fertilizer",body="A fertilizer bag is tied shut inside a supply pack. Its seams are dusted yellow-green. The page under it lists spray-plot rows and a delivery, no recipient.",anchor={map="EkronStashMap3",mark=1}},
-- T0037
{id="t0037-01",kind="set",pieces={"Stapler","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Stapler and first aid kit",body="The stapler and first aid kit are sealed together, never opened. Soot darkens the bundle. The clean outlines suggest it was packed before the fire.",anchor={map="EkronStashMap4",mark=1}},
-- T0038
{id="t0038-01",kind="set",pieces={"Bandage","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Bandage and notebook",body="The school notebook pairs a bandage with a seed-treatment plot note. Children got a rash on their arms after the rows were sprayed. The last line asks who will collect the used kit.",anchor={map="EkronStashMap5",mark=1}},
-- T0039
{id="t0039-01",kind="set",pieces={"Bleach","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Bleach and water bottle",body="A bottle of bleach sits beside a copied warning. The water bottle next to it still has its cap sealed. A note says the caller was told to wait for instructions.",anchor={map="EkronStashMap6",mark=1}},
-- T0040
{id="t0040-01",kind="set",pieces={"Map","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Map and pencil",body="The map shows a route along the sprayed fields. Someone pencilled a return arrow but left no destination. A note asks if the field check on the wilted rows still happens.",anchor={map="EkronStashMap7",mark=1}},
-- T0041
{id="t0041-01",kind="set",pieces={"HolePuncher","Clipboard"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hole punch and clipboard",body="Matching white stripes cross the hole punch and the clipboard. A name-sized patch on the hole punch has been scrubbed bare.",anchor={map="IrvingtonStashMap2",mark=1}},
-- T0042
{id="t0042-01",kind="set",pieces={"WalkieTalkie1","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Walkie-talkie and paper",body="The paper says to radio on the walkie talkie before turning back. It lists the spray crew under visitors for the route.",anchor={map="IrvingtonStashMap3",mark=1}},
-- T0043
{id="t0043-01",kind="set",pieces={"SheetPaper2","Pencil"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Paper and pencil",body="Someone penciled notes about who needed rides out. The paper has an official stamp: road closure, no exceptions. They never made it.",anchor={map="IrvingtonStashMap4",mark=1}},
-- T0044
{id="t0044-01",kind="set",pieces={"Eraser","HandTorch"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="eraser and hand torch",body="The eraser and torch are caked in yellow-green spray dust. It's thick on the handle and pressed into the eraser's grooves. The smell is chemical-sweet and fresh-cut stalks.",anchor={map="IrvingtonStashMap5",mark=1}},
-- T0045
{id="t0045-01",kind="set",pieces={"HandTorch","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hand torch and map",body="The hand torch rests on the map. Someone marked a route with times at each stop. The last address has no time beside it.",anchor={map="IrvingtonStashMap6",mark=1}},
-- T0046
{id="t0046-01",kind="set",pieces={"Notebook","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="notebook and seed bag",body="I find a notebook logging pesticide applications at triple strength. The seed bag beside it says experimental field trial batch nine. The last entry notes faster germination than any prior test.",anchor={map="IrvingtonStashMap7",mark=1}},
-- T0047
{id="t0047-01",kind="set",pieces={"Pen","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pen and bath towel",body="Red and blue cord join the black pen to the bath towel. The red cord is cut. The blue cord ends in a sealed knot.",anchor={map="IrvingtonStashMap8",mark=1}},
-- T0048
{id="t0048-01",kind="set",pieces={"Hammer","Nails"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="hammer and nails",body="I find a hammer and nails by notes on the test plot spray cycle. Posts along the crop rows needed repair before application. The pesticide batch number is crossed out and rewritten.",anchor={map="IrvingtonStashMap9",mark=1}},
{id="t0048-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Diary page",body="Notebook page: “fortify here” meant boards over the garden door before the next patrol came through. A man with a clipboard took our names and told us to say nothing about the count.\n\nMy mother put it with the household bills so it would not be thrown away. It was the only part of the week that still had a date.",anchor={map="IrvingtonStashMap9",note=1}},
{id="t0048-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Margin note: heart is the cot where farm sprayers slept. Their boots tracked yellow dust across the bedroom. The family used that cot two nights later. I could smell the sweetness on the blanket for days.",anchor={map="IrvingtonStashMap9",note=2}},
{id="t0048-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="On the photograph back: second heart, our spare blanket. I rinsed green flecks from it after the seed-treatment men left, then the well began tasting of pennies.\n\nI kept the corner of the old page in my pocket. The flecks came out of the blanket slowly, and the well water was cloudy for days.",anchor={map="IrvingtonStashMap9",note=3}},
{id="t0048-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Torn notebook page: the third heart is the room lent to two pasture-test workers. One wrote that the calves refused water after the pasture was sprayed.\n\nTheir boots by the door were caked with the same pale dust as the pasture gate. I wrote this down before their truck left.",anchor={map="IrvingtonStashMap9",note=4}},
{id="t0048-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Personal note: at the fourth heart we shut the window during the field misting. The kitchen herbs curled by supper, hours after the spraying.\n\nI set the page aside to show the neighbor when she returned. Her porch was empty by the time the light was good enough to read it.\n\nThere may be a simple reason for the change. The seed supplier could not tell us what the first mix contained.",anchor={map="IrvingtonStashMap9",note=5}},
{id="t0048-07",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Handwritten letter",body="Letter draft: the fifth heart was for the baby room. At the roadblock they said evacuations halted, would not document it.\n\nThere was a numbered tag on our door the next morning. I wrote the date here while I could still remember it.",anchor={map="IrvingtonStashMap9",note=6}},
-- T0049
{id="t0049-01",kind="set",pieces={"RedPen","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Red pen and camera",body="Chalk numbers run across the red pen and the camera. The count skips one place. Then it picks up again in a different hand.",anchor={map="IrvingtonStashMap10",mark=1}},
-- T0050
{id="t0050-01",kind="set",pieces={"Book","LetterHandwritten"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Book and handwritten letter",body="The book is wrapped in a note about a family visit. The back lists spray dates for the bean rows by the garden hose. It warns to keep the hose off the marked ground.",anchor={map="LouisvilleStashMap2",mark=1}},
-- T0051
{id="t0051-01",kind="set",pieces={"Screwdriver","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Screwdriver and notebook",body="The notebook logs repairs, key sign-out and return dates. Someone returned the basement key three days before the work ended. The screwdriver's still covered in rust from down there.",anchor={map="LouisvilleStashMap3",mark=1}},
-- T0052
{id="t0052-01",kind="set",pieces={"Sledgehammer","PetrolCan"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Sledgehammer and petrol can",body="The sledge is marked for a station delivery. The fuel can is logged empty before the driver's return. The receipt leaves the destination blank.",anchor={map="LouisvilleStashMap4",mark=1}},
-- T0053
{id="t0053-01",kind="set",pieces={"Bag_Schoolbag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="School bag and water bottle",body="The school bag and water bottle are listed for pickup at the gym. The driver marked the family as transferred before the pickup time.",anchor={map="LouisvilleStashMap5",mark=1}},
-- T0054
{id="t0054-01",kind="set",pieces={"SeedBag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Seed bag and water bottle",body="The seed bag sits beside a water bottle labelled for the back plot. A note says to stop watering until the test results arrive.",anchor={map="LouisvilleStashMap6",mark=1}},
-- T0055
{id="t0055-01",kind="set",pieces={"BluePen","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Blue pen and briefcase",body="The blue pen and briefcase are wrapped in a child's raincoat. One stayed dry, but the other was left in road mud.",anchor={map="LouisvilleStashMap7",mark=1}},
-- T0056
{id="t0056-01",kind="set",pieces={"Pills","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="pills and notebook",body="The notebook lists fields sprayed with the new formula. The pills are for headaches from fumes, stronger than expected. Last note says symptoms match the livestock reports.",anchor={map="LouisvilleStashMap8",mark=1}},
-- T0057
{id="t0057-01",kind="set",pieces={"HuntingRifle","CannedCorn"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hunting rifle and canned corn",body="A hunting rifle tied to a corn can with wire. Both tagged for checkpoint supply run. I can't read the return time - someone burned it off the tags.",anchor={map="LouisvilleStashMap9",mark=1}},
-- T0058
{id="t0058-01",kind="set",pieces={"Bread","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Bread and sheet of paper",body="A bread receipt is tucked inside a note. The back lists garden rows sprayed on a given day. It also lists produce from them that never reached the house.",anchor={map="LouisvilleStashMap10",mark=1}},
-- T0059
{id="t0059-01",kind="set",pieces={"MagnifyingGlass","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Magnifying glass and map",body="A broken barrier board crushed the glass against the folded map. The clean undersides look like both were here before the road closed.",anchor={map="LouisvilleStashMap11",mark=1}},
-- T0060
{id="t0060-01",kind="set",pieces={"Pizza","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Pizza and water bottle",body="The pizza sat by the field station tent. They filled the water bottle from a hose that rinses sprayers. Green residue still coats the connection.",anchor={map="LouisvilleStashMap12",mark=1}},
-- T0061
{id="t0061-01",kind="set",pieces={"Hammer","Garbagebag"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hammer and garbage bag",body="The sweep report calls this gate secure. A tied garbage bag holds the latch. There's a hammer and note to check what's inside.",anchor={map="LouisvilleStashMap13",mark=1}},
-- T0062
{id="t0062-01",kind="set",pieces={"Nails","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Nails and sheet of paper",body="Nails hold a sheet of paper to the wall. It tells everyone to wait outside while the boards cure. The radio call time says half hour.",anchor={map="LouisvilleStashMap14",mark=1}},
-- T0063
{id="t0063-01",kind="set",pieces={"SewingKit","WalkieTalkie1"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Sewing kit and walkie-talkie",body="Three pickup dots mark the sewing kit and the hand radio. Two were scratched away, with no wear around them.",anchor={map="LouisvilleStashMap15",mark=1}},
-- T0064
{id="t0064-01",kind="set",pieces={"Bag_Schoolbag","Map"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="School bag and map",body="A schoolbag holds a map with a route south marked out. The same map shows sprayed fields beside the eastern road. A warning pencilled in says to avoid the wet crops.",anchor={map="LouisvilleStashMap16",mark=1}},
-- T0065
{id="t0065-01",kind="set",pieces={"Pistol","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pistol and sheet of paper",body="A pistol is wrapped in a store receipt. A note says to leave the remaining supplies for the next family. The collection time is earlier than the closure notice.",anchor={map="MarchRidgeStashMap2",mark=1}},
-- T0066
{id="t0066-01",kind="set",pieces={"Bread","Map"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="bread and map",body="The bread tastes faintly chemical underneath the wrapper. The map shows crop dusting routes for the surrounding farms. The spray concentration was crossed out and rewritten higher.",anchor={map="MarchRidgeStashMap3",mark=1}},
-- T0068
{id="t0068-01",kind="set",pieces={"Bag_ALICEpack","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Backpack and map",body="The pack was logged in before this map shows evacuation routes. They delivered supplies before marking where people were stuck.",anchor={map="MarchRidgeStashMap4",mark=1}},
-- T0069
{id="t0069-01",kind="set",pieces={"BaseballBat","Bandage"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Baseball bat and bandage",body="A bandage and a bat share a medical-center bag. The note on its tie says to keep the back room quiet. That's until the wash is finished.",anchor={map="MarchRidgeStashMap5",mark=1}},
-- T0070
{id="t0070-01",kind="set",pieces={"Hammer","Nails"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hammer and nails",body="These nails are barely driven in, hammer lying right there. The barricade checklist is marked complete. Nobody came back to finish.",anchor={map="MarchRidgeStashMap6",mark=1}},
-- T0071
{id="t0071-01",kind="set",pieces={"Notebook","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook and water bottle",body="The notebook lists fever dates beside field spraying schedules. Someone marked days when people drank from the stream below. The water bottle sits empty. Every fever came within days of spraying.",anchor={map="MarchRidgeStashMap7",mark=1}},
-- T0072
{id="t0072-01",kind="set",pieces={"Thread","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Thread and first aid kit",body="Pale seed-treatment grit and feed dust cake the thread and kit. The kit's latch is gummed with sweet residue.",anchor={map="MarchRidgeStashMap8",mark=1}},
-- T0073
{id="t0073-01",kind="set",pieces={"Pistol","Bread"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pistol and bread",body="A pistol and bread, standard issue both. Left behind before the next supply run. Looks like they got pulled out in a hurry.",anchor={map="MarchRidgeStashMap9",mark=1}},
-- T0074
{id="t0074-01",kind="set",pieces={"Book","HandTorch"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Book and hand torch",body="A book rests with a hand torch. A note inside warns to avoid the treated ground until it dries. A blessing is written at the end.",anchor={map="MarchRidgeStashMap10",mark=1}},
-- T0075
{id="t0075-01",kind="set",pieces={"Hammer","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hammer and sheet of paper",body="The sheet lists tools returned after containment. This hammer's serial number isn't on it. Extra tools, no record.",anchor={map="MulStashMap1",mark=1}},
-- T0076
{id="t0076-01",kind="set",pieces={"SeedBag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Seed bag and water bottle",body="The seed packet is kept with a bottle labelled for the plot. A note asks the next visitor to wait for the field reading. It says not to open either until then.",anchor={map="MulStashMap2",mark=1}},
-- T0077
{id="t0077-01",kind="set",pieces={"Pistol2","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pistol and sheet of paper",body="Found a pistol on a sheet of paper. The sheet lists a weapon transfer order. Receiving signature is blank. Nobody ever came to pick it up.",anchor={map="MulStashMap11",mark=1}},
-- T0078
{id="t0078-01",kind="set",pieces={"Needle","Clipboard"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Needle and clipboard",body="The sewing needle and clipboard carry the same black paint. A fresh scrape shows an older evacuation color underneath.",anchor={map="MulStashMap3",mark=1}},
-- T0079
{id="t0079-01",kind="set",pieces={"Bandage","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Bandage and first aid kit",body="A first aid kit and bandage by the side door. Orders routed people through here. The main entrance was already cleared.",anchor={map="MulStashMap4",mark=1}},
-- T0080
{id="t0080-01",kind="set",pieces={"Pistol","CannedCorn"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="pistol and canned corn",body="This corn can has a trial batch sticker from the co-op. The field beside it is rotting on the stalk. A pistol lies next to it.",anchor={map="MulStashMap12",mark=1}},
-- T0081
{id="t0081-01",kind="set",pieces={"Notebook","Pencil"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Notebook and pencil",body="One page is torn out of the notebook. There's a route copy with a blank arrival box. A pencilled note asks if the driver should wait or report it complete.",anchor={map="MulStashMap5",mark=1}},
-- T0082
{id="t0082-01",kind="set",pieces={"Bag_ALICEpack","Pistol"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="backpack and pistol",body="The alicepack reeks of crop spray. A pistol lies on top. Field application equipment hangs from the straps.",anchor={map="MulStashMap13",mark=1}},
-- T0083
{id="t0083-01",kind="set",pieces={"Hammer","Bandage"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hammer and bandage",body="A hammer and bandage on some checkpoint paperwork. No exit time logged. The person assigned to carry both never made it out.",anchor={map="MulStashMap6",mark=1}},
-- T0084
{id="t0084-01",kind="set",pieces={"TinOpener","Pills"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Tin opener and pills",body="These never made it out. Tin opener sealed, pills unopened. Tag says close at dusk, leave head count blank.",anchor={map="MulStashMap7",mark=1}},
-- T0085
{id="t0085-01",kind="set",pieces={"Yarn","HandTorch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Yarn and hand torch",body="Road dust coats the yarn and the hand torch. But their ties are clean and newly cut. I think the bundle was repacked after travel.",anchor={map="MulStashMap8",mark=1}},
-- T0086
{id="t0086-01",kind="set",pieces={"HandTorch","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Hand torch and notebook",body="A field notebook is closed under a torch. Its last page lists soil and leaf samples from sprayed plots. It asks whether the sample was taken before or after the second spray.",anchor={map="MulStashMap9",mark=1}},
-- T0087
{id="t0087-01",kind="set",pieces={"LeatherStrips","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Leather strips and bath towel",body="The leather strips and towel are wedged beneath unused warning tape. Footprints pass around the bundle, not toward it.",anchor={map="MulStashMap10",mark=1}},
-- T0088
{id="t0088-01",kind="set",pieces={"Hammer","Nails"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Hammer and nails",body="A note around the hammer and nails is for the next crew. It says to stay out of the sprayed orchard rows till dry. Board the cellar vents against drift; a name reads \"wait.\"",anchor={map="MulStashMap14",mark=1}},
-- T0089
{id="t0089-01",kind="set",pieces={"Bandage","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Bandage and notebook",body="The bandage wrapper is tucked into a route book. The clinic stop is stamped complete. But the patient's return line isn't signed yet.",anchor={map="MulStashMap15",mark=1}},
-- T0090
{id="t0090-01",kind="set",pieces={"RadioBlack","Pistol"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Black radio and pistol",body="A black radio and pistol left by the roadside gate. Someone was monitoring the crop program broadcasts here. The last transmission asked about backup generators at the silos.",anchor={map="MulStashMap16",mark=1}},
-- T0091
{id="t0091-01",kind="set",pieces={"Garbagebag","Bread"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Bread and garbage bag",body="I found bread near a garbage bag with an official tag. The tag said 'stay inside' and listed two removal dates. The first date is checked off but they returned.",anchor={map="MulStashMap17",mark=1}},
-- T0092
{id="t0092-01",kind="set",pieces={"Pistol","PetrolCan"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="pistol and petrol can",body="The sprayer rig fuel gauge reads empty, petrol can beside it. Field trial notes list experimental compound batches. A pistol lies on the application schedule sheet.",anchor={map="MulStashMap18",mark=1}},
-- T0093
{id="t0093-01",kind="set",pieces={"WaterBottle","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Water bottle and notebook",body="The notebook shows returns scheduled before departures. Dates don't add up. The water bottle is marked for someone not listed inside.",anchor={map="MulStashMap19",mark=1}},
-- T0094
{id="t0094-01",kind="set",pieces={"Broom","Camera"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Broom and camera",body="The broom has a treated-seed stain. The camera lens is smeared with the same pink seed coating. One rope knot holds both together.",anchor={map="RiversideStashMap1",mark=1}},
-- T0095
{id="t0095-01",kind="set",pieces={"Soap2","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="soap and briefcase",body="The briefcase clasp is broken, the soap wedged inside. Route maps inside mark crossings safe that I saw burning.",anchor={map="RiversideStashMap2",mark=1}},
-- T0096
{id="t0096-01",kind="set",pieces={"Wine","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Wine and sheet of paper",body="The bottle's neck is crusted with sweet residue. A note says keep the back room aired after the pesticide test. The food order is still unpaid.",anchor={map="RiversideStashMap3",mark=1}},
-- T0097
{id="t0097-01",kind="set",pieces={"Pills","Bandage"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pills and bandage",body="The pills sit with a bandage and a transfer document. Delivery is marked complete on the form. No one signed for them.",anchor={map="RiversideStashMap4",mark=1}},
-- T0098
{id="t0098-01",kind="set",pieces={"BaseballBat","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="baseball bat and sheet of paper",body="The paper warns to stay clear of the sprayed fields.\nIt's dated two days after the application.\nA bat's left beside it.",anchor={map="RiversideStashMap5",mark=1}},
-- T0099
{id="t0099-01",kind="set",pieces={"Pistol","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pistol and notebook",body="The pistol lies on a notebook of quarantine handoffs. Last entry records a room transfer. No recipient signed.",anchor={map="RiversideStashMap6",mark=1}},
-- T0100
{id="t0100-01",kind="set",pieces={"CannedCorn","LetterHandwritten"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Canned corn and handwritten letter",body="The note says every item was collected before the westbound trip. A food tin is still here. It's beside an argument about who should be left in charge.",anchor={map="RiversideStashMap7",mark=1}},
-- T0101
{id="t0101-01",kind="set",pieces={"Bread","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Bread and water bottle",body="Bread and a water bottle tied to a note for whoever comes next. It says to eat before leaving. The back has a sighting dated after they closed this route.",anchor={map="RiversideStashMap8",mark=1}},
-- T0102
{id="t0102-01",kind="set",pieces={"PetrolCan","Pills"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Petrol can and pills",body="I found a petrol can marked for a medical run. Pills spilled nearby. A field worker got sick. They must have stopped here for help.",anchor={map="RiversideStashMap9",mark=1}},
-- T0103
{id="t0103-01",kind="set",pieces={"Sponge","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="sponge and map",body="The sponge and map are tied with cut quarantine tape. Six marks are scratched on the sponge but only four crossed off. Both evacuation routes on the map end at checkpoint barriers.",anchor={map="RiversideStashMap10",mark=1}},
-- T0104
{id="t0104-01",kind="set",pieces={"Notebook","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook and pencil",body="A notebook page of spray instructions for the bean rows is gone. A pencil note asks if the chemical sample goes on the next run.",anchor={map="RosewoodStashMap1",mark=1}},
-- T0105
{id="t0105-01",kind="set",pieces={"Pistol","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pistol and map",body="The map has the last stop marked complete. Pistol signed out there but never signed back in. They knew it was one-way.",anchor={map="RosewoodStashMap2",mark=1}},
-- T0106
{id="t0106-01",kind="set",pieces={"Hammer","Nails"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Hammer and nails",body="Someone left a hammer and nails by the window with a note. Keep it shut until the ground outside dries from the spraying. The meeting time for everyone is written in the same hand.",anchor={map="RosewoodStashMap3",mark=1}},
-- T0107
{id="t0107-01",kind="set",pieces={"Bag_ALICEpack","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Backpack and water bottle",body="The pack's mostly empty, just a water bottle left inside. The card says pack light and leave before dawn. They promised pickup at sunrise but nobody ever came.",anchor={map="RosewoodStashMap4",mark=1}},
-- T0109
{id="t0109-01",kind="set",pieces={"Bread","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Bread and water bottle",body="The bread and water bottle are marked for route pickup only. Someone crossed out the driver's name. It still says wait for the family.",anchor={map="RosewoodStashMap5",mark=1}},
-- T0110
{id="t0110-01",kind="set",pieces={"ToiletPaper","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Toilet paper and water bottle",body="The toilet paper and water bottle are packed with treated seed. Every kernel has the same cracked green coating.",anchor={map="WorldStashMap1",mark=1}},
-- T0111
{id="t0111-01",kind="set",pieces={"Hammer","Nails"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hammer and nails",body="The hammer and nails were placed here before the cordon went up. Someone on the inside prepped them for barricading. They were staged days before the public evacuation order.",anchor={map="WorldStashMap2",mark=1}},
-- T0112
{id="t0112-01",kind="set",pieces={"PetrolCan","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Petrol can and pencil",body="The petrol can has pencil marks on the side tracking fills. Last mark says full but it's bone dry. Someone was logging lies.",anchor={map="WorldStashMap3",mark=1}},
{id="t0112-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Repair note: flush the field sprayer at the wrench mark before returning it. The pump seal had softened and the mechanic wrote that the rinse water stung his hands.\n\nThe tank held the same treatment mix as the whole season's spray rounds. I kept the page because the batch number was circled twice.",anchor={map="WorldStashMap3",mark=2}},
{id="t0112-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Cash receipt: fuel at the marked stop, charged to the late-season crop trial. The driver added that the tank was full before the detour to the plots and nearly dry afterward.\n\nThe trial lead never signed it. I used the margin to note the plot numbers the driver listed.",anchor={map="WorldStashMap3",note=1}},
{id="t0112-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Notebook line under “you’ll need it”: reserve another can for the second pasture pass. The first crew came home coughing before any emergency convoy used the road.\n\nMy mother put it with the household bills so it would not be thrown away. It was the only part of the week that still had a date.\n\nI do not know which of the two accounts was repeated afterward. The older one is the one I had in my hands that day.",anchor={map="WorldStashMap3",note=2}},
-- T0113
{id="t0113-01",kind="set",pieces={"Tissue","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Tissues and first aid kit",body="The tissues and first aid kit are sealed together, never opened. Soot darkens the bundle. The clean outlines look like it was packed before the fire.",anchor={map="WorldStashMap4",mark=1}},
-- T0114
{id="t0114-01",kind="set",pieces={"Bag_ALICEpack","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Backpack and seed bag",body="A pack of supplies is hidden with the seed bag. A note asks the next visitor to keep inspectors from the soil kit.",anchor={map="WorldStashMap5",mark=1}},
-- T0115
{id="t0115-01",kind="set",pieces={"Candle","Clipboard"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Candle and clipboard",body="Matching white stripes cross the candle and the clipboard. A name-sized patch on the candle has been scrubbed bare.",anchor={map="WorldStashMap6",mark=1}},
{id="t0115-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Photograph back: the cross marks the store used by the crop trial. One sample crate was removed before the seed inventory and left a blue outline on the floor.\n\nThe outline matched the blue coating on the trial seed. I saved the photo for the name written on the reverse.",anchor={map="WorldStashMap6",mark=2}},
{id="t0115-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Sample log sheet",body="The jars were for soil samples from the test plots. Someone wrote the new spray made the plants grow wrong. All the gear is still here, left where the crew dropped it. I found beetles in one jar that should have been dead.",anchor={map="WorldStashMap6",note=1}},
{id="t0115-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Personal farm log: the old packing floor was too big for one field crew. The trial team used only one bay, yet fresh powder reached the other bays overnight, settling on the sacks.\n\nWe swept it twice. The fine grit came back each morning on the unplanted side too.",anchor={map="WorldStashMap6",note=2}},
{id="t0115-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Receipt margin: count the sealed seed sacks again at the cross. The driver signed for twelve, while only eleven appear on the field tally.\n\nNobody agreed on whose list this belonged to. I left it where the next person would look for the things we still owed each other.\n\nI could have mistaken the order in which those things happened. I could not mistake the empty place left for the person we had been waiting for.",anchor={map="WorldStashMap6",note=3}},
{id="t0115-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="On a faded photograph: the handwritten name by the cross belonged to the man counting treated rows. His tally ends one row before the plants turned black.\n\nI meant to ask him about the last row. The blackened stalks were still standing the next day.",anchor={map="WorldStashMap6",note=4}},
-- T0116
{id="t0116-01",kind="set",pieces={"Bandage","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Bandage and water bottle",body="The water bottle is tagged for the infected area. The field note says to fill it before the next crew enters. A bandage wrapper is folded around the cap.",anchor={map="WorldStashMap7",mark=1}},
-- T0117
{id="t0117-01",kind="set",pieces={"Notebook","Pencil"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Notebook and pencil",body="The notebook's departure time is filled in. The destination line stays blank. A margin note says to wait for the updated route. The pencil lies across the page.",anchor={map="WorldStashMap8",mark=1}},
-- T0118
{id="t0118-01",kind="set",pieces={"Notebook","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="notebook and sheet of paper",body="I found batch codes and dilution rates logged in the notebook. The sheet marks the same test plots for a second treatment.",anchor={map="WorldStashMap9",mark=1}},
{id="t0118-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Warehouse note: keep the empty crates for soil cores from the southern trial farms. Three returned damp and smelling of solvent, though the manifest lists them unused.\n\nSomeone said the smell was only from cleaning. The soil inside had the same pale film as the treated rows.",anchor={map="WorldStashMap9",note=1}},
{id="t0118-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Diary entry: the railyard pickup carried seed sacks and rinse drums before dawn. By breakfast the switchman’s eyes burned; the public closure came later.\n\nThe mark was made in a hurry, before the queue moved. I checked it twice against the people standing with me.\n\nI wanted to keep a clean copy, but the stain is where the first entry was crossed out. I have not tried to improve it.",anchor={map="WorldStashMap9",note=2}},
{id="t0118-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Driver's torn page: the Muldraugh route was crossed out after the field team reported foam in the drainage ditch below the treated plots. No replacement destination appears.\n\nI kept the page on the kitchen table. The ditch water left a pale ring on every boot that crossed it.",anchor={map="WorldStashMap9",note=3}},
{id="t0118-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Sample Log",body="I found route notes with collection points marked in faint pencil. The sample counts climb steadily heading north from the trial farms. Each bag carries the same dark stain as the treated seed.",anchor={map="WorldStashMap9",note=4}},
{id="t0118-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Notebook from the offices: four crop-test invoices, no company name, all paid in cash. A pencil note says the program agent collected the carbon copies.\n\nEach invoice lists the same seed treatment, billed per acre, for fields nobody here had leased.",anchor={map="WorldStashMap9",note=5}},
{id="t0118-07",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Wash record",body="The equipment shed took three wash cycles after the tanks spilled. Residue still tested above the pesticide safety threshold. I found the warning labels peeling off the empty drums.",anchor={map="WorldStashMap9",note=6}},
{id="t0118-08",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Personal rail log: none of the trains would start after the trial shipment arrived. The same oily grit coated each air intake, but the repair report calls it ordinary dust.\n\nThe grit smelled of the same treatment as the crates it came in.",anchor={map="WorldStashMap9",note=7}},
-- T0119
{id="t0119-01",kind="set",pieces={"Matches","HandTorch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Matches and hand torch",body="The matches and hand torch smell sharply of bleach. Mud outlines between them look like something was taken.",anchor={map="WorldStashMap10",mark=1}},
{id="t0119-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Laundry receipt: coveralls from the second circle carried orange pollen from the sprayed test rows. The clerk noted numb fingers after handling the bag.\n\nThe pollen would not wash out, even after the third rinse, and the water smelled of the spray tank.",anchor={map="WorldStashMap10",mark=2}},
{id="t0119-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Meal receipt back: six lunches went to the greenhouse crew at the third circle. Two were untouched; beside them someone wrote, \"metal taste after noon spray.\"\n\nThe greenhouse tomatoes had curled by evening.",anchor={map="WorldStashMap10",mark=3}},
{id="t0119-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Receipt",body="Photograph note: the fourth circle shows where three cars were stopped behind the garage and their drivers lined up for a head count. Every plate was copied onto a list, and the road beyond was blocked with a sawhorse.\n\nThe list was numbered in chalk on the garage door.",anchor={map="WorldStashMap10",mark=4}},
{id="t0119-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Pocket ledger: gas at this circle was charged to the orchard rig. The return mileage exceeds the marked spray route by forty miles.\n\nThe rig's tank still held mix, and the hoses were crusted with yellow residue.",anchor={map="WorldStashMap10",note=1}},
{id="t0119-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Torn note under the clothes label: bag the trial coveralls separately from the household wash. My wrists blistered while tying the second bag.\n\nThe cloth was stiff with dried spray and smelled of the crop sprayer.",anchor={map="WorldStashMap10",note=2}},
{id="t0119-07",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Handwritten letter",body="Receipt from the marked restaurant: lunches for the crop crew, plus soap and bottled water. A handwritten line says the tap smelled sharp, like the spray mix, before closing.\n\nThe crew's hands were raw and cracked.",anchor={map="WorldStashMap10",note=3}},
{id="t0119-08",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Diary page",body="Mileage page: four cars left for the checkpoint, three returned to the garage. The blank driver line sits beside a note to keep the count off the radio.\n\nThe fourth car was never logged back in.",anchor={map="WorldStashMap10",note=4}},
{id="t0119-09",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Garage receipt at the car label: rinse three crop-study vehicles and keep the fourth outside. The fourth plate is the only one with treated-seed dust still in the trunk.\n\nThe rinse bill itself was small and ordinary.",anchor={map="WorldStashMap10",note=5}},
{id="t0119-10",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Application Record",body="I found a page from the application schedule for the test fields. Batch seven was marked at three times the normal concentration. Someone had written in the margin that the dilution system jammed.",anchor={map="WorldStashMap10",note=6}},
-- T0120
{id="t0120-01",kind="set",pieces={"RadioReceiver","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Radio receiver and sheet",body="The sheet shows signal dropped during crop spraying tests. A note says 'check field power' by the radio receiver. Calibration was never completed.",anchor={map="WorldStashMap11",mark=1}},
{id="t0120-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Equipment log",body="The monitor stopped during the night spray on the trial plots. Readings before dropout showed values I had never seen before. Equipment was intact but the plots looked different at dawn.",anchor={map="WorldStashMap11",note=1}},
{id="t0120-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Torn meter log: near six gigahertz, power dipped as the spraying crew entered the eastern field. The station batteries were full and no storm was recorded.\n\nThe dips came with every pass of the spray rig and stopped when it left.",anchor={map="WorldStashMap11",note=2}},
{id="t0120-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Letter draft: ask the program office to compare the Lexington receiver with two leaf samples. The samples carry the same gray film found inside the tower cabinet.\n\nThe leaves came from the treated field beside the tower.",anchor={map="WorldStashMap11",note=3}},
{id="t0120-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Monitor Photograph",body="The crop monitor had brown residue inside and smelled chemical. The spray log showed treatments I never authorized or applied.\n\nWhen I touched the panel my hands stained the same color. The marks stayed even after scrubbing with soap and water.",anchor={map="WorldStashMap11",note=4}},
{id="t0120-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Technician's notebook: the cross marks the receiver used for crop-weather telemetry. It failed whenever the treated field pump ran, then recovered after the pump stopped.\n\nI logged the pump times beside each dropout. They lined up every day.",anchor={map="WorldStashMap11",note=5}},
-- T0121
{id="t0121-01",kind="set",pieces={"Pills","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pills and water bottle",body="I find pills and a water bottle next to a camp roster.\nSomeone's name has no pickup mark.\nA note asks if their dose ever reached the main office.",anchor={map="WorldStashMap12",mark=1}},
-- T0122
{id="t0122-01",kind="set",pieces={"LetterHandwritten","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="handwritten letter and seed bag",body="A seed bag has a handwritten letter tucked inside. The note mentions the test treatment wasn't ready yet. It describes crop rows dying faster than anyone expected.",anchor={map="WorldStashMap13",mark=1}},
-- T0123
{id="t0123-01",kind="set",pieces={"Lighter","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Lighter and bath towel",body="Red and blue cord joins the lighter to the bath towel. The red route is cut, and the blue route ends in a sealed knot.",anchor={map="WorldStashMap14",mark=1}},
-- T0124
{id="t0124-01",kind="set",pieces={"Notebook","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook and water bottle",body="A water bottle rests on a notebook. Last entry warns not to water until test results return. Something about checking the treatment program first.",anchor={map="WorldStashMap15",mark=1}},
-- T0125
{id="t0125-01",kind="set",pieces={"Extinguisher","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Fire extinguisher and camera",body="Chalk numbers run across the extinguisher and the camera. The count skips one place, then goes on in a different hand.",anchor={map="WorldStashMap16",mark=1}},
{id="t0125-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Diary page",body="Diary line at the first trap: a torn numbered tag was caught beneath the spring. Its number belongs to a household that the return list calls cleared.\n\nThe tag still had a strip of tape stuck to it.",anchor={map="WorldStashMap16",note=1}},
{id="t0125-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Camp log: the pasture-study team slept here for three nights. On the fourth morning their cook poured out the water because it smelled medicinal.\n\nMy mother put it with the household bills so it would not be thrown away. It was the only part of the week that still had a date.\n\nI do not know which of the two accounts was repeated afterward. The older one is the one I had in my hands that day.",anchor={map="WorldStashMap16",note=2}},
{id="t0125-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Field Log",body="I found the test drums behind the north fence marker.\nOne was leaking a milky fluid onto the ground.\nEvery plant beneath it had turned black and brittle.",anchor={map="WorldStashMap16",note=3}},
{id="t0125-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Photograph back: the second trap contained a torn soil-sample bag, not an animal. Blue granules beneath it matched the coating on the trial seed.\n\nThe granules had eaten a ring of bare ground around the bag.",anchor={map="WorldStashMap16",note=4}},
{id="t0125-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Spray log",body="Pulled this from a crop duster's cab after he stumbled out. Last page documents the new orange compound on the south fields. His script goes crooked, then just orange fingerprints.",anchor={map="WorldStashMap16",note=5}},
{id="t0125-07",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Handwritten letter",body="Road-crew receipt: barriers were moved downhill after the road was closed to traffic. The billed hours match the night the patrol took names from the houses along the road.\n\nA checkpoint was left standing past the culvert.",anchor={map="WorldStashMap16",note=6}},
{id="t0125-08",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Application notes",body="Followed the markers to the spray zone and counted the tanks. Seven canisters went into the test plot but only six came out.\n\nThe missing one must have ruptured in the trial rows. I documented the chemical burn pattern for the review.",anchor={map="WorldStashMap16",note=7}},
-- T0126
{id="t0126-01",kind="set",pieces={"Camera","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Camera and notebook",body="A camera is packed with a field notebook. The notebook says to photograph the blind side of the fence. The sensor check is marked complete before the crew arrives.",anchor={map="WorldStashMap17",mark=1}},
-- T0127
{id="t0127-01",kind="set",pieces={"AlcoholWipes","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="alcohol wipes and briefcase",body="The briefcase holds evacuation lists with half the names crossed out. Wipes scatter from a medic pouch stamped for checkpoint nine. Both wrapped in a small raincoat, dropped here in the roadside mud.",anchor={map="WorldStashMap18",mark=1}},
{id="t0127-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Farm diary: the first fire started beneath the assay table after a field sample cracked. The wet soil burned blue before any building caught.\n\nThe sample came from the treated plots, and the flame smelled sweet and chemical.",anchor={map="WorldStashMap18",note=1}},
{id="t0127-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Diary entry: beside the second fire mark lay a scorched tray from the soil assay. Its unburned label says the orchard batch was reapplied after rain.\n\nThe tray rim was crusted with the same residue as the sprayer nozzles.",anchor={map="WorldStashMap18",note=2}},
{id="t0127-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Photograph back: the third fire began among returned seed sacks, not the nearby lumber. Violet grains remained in the seams after the flames went out.\n\nThe lumber beside them was barely scorched.",anchor={map="WorldStashMap18",note=3}},
{id="t0127-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Farm log: smoke at the fourth fire rose from the rinse pit after the trial crew emptied its hoses. The grass died in a clean ring before dusk.\n\nThe pit water still foamed when stirred.",anchor={map="WorldStashMap18",note=4}},
{id="t0127-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Torn notebook page: the fifth fire followed a split treatment drum at the trial plot. Water spread the burning film, so we covered it with field soil and left.\n\nThe soil darkened and smoked where the film touched it.",anchor={map="WorldStashMap18",note=5}},
{id="t0127-07",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Application note",body="New pesticide formula dissolved my rubber boots in the field. Amber gel coating every plant and pooling in the furrows. My hands itch where droplets landed on bare skin.",anchor={map="WorldStashMap18",note=6}},
{id="t0127-08",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Diary page",body="Letter draft: the seventh fire caught damp hay by the road. A deputy asked us to call it a lantern accident and to say nothing of the others.\n\nThere was no lantern, only a patrol truck parked at the fence.",anchor={map="WorldStashMap18",note=7}},
{id="t0127-09",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Diary line: the eighth fire glowed before sunrise around bags from the night application. No homes were burning and no one had run for the road.\n\nThe bags were treated seed, split at the seams.",anchor={map="WorldStashMap18",note=8}},
{id="t0127-10",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Delivery Receipt",body="The application rate on the invoice did not match the concentration. Dead frogs appeared in the drainage before the second field was done. The container labels were different from what we requested.",anchor={map="WorldStashMap18",note=9}},
{id="t0127-11",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Maintenance Photo",body="The tenth sprayer fire started beneath the tank mount. Treatment foam had crystallized across the engine housing. The residue pattern matched the previous equipment failures.",anchor={map="WorldStashMap18",note=10}},
{id="t0127-12",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Field notes",body="The research pens held only bones and that white powder. It coated the feed pellets, the water lines, even the soil samples. I found dosage charts pinned above each station.",anchor={map="WorldStashMap18",note=11}},
{id="t0127-13",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Handwritten letter",body="Farm diary: the twelfth fire consumed only the flagged crop rows. Untreated rows on either side stayed green until the next rain.\n\nThe flags carried the trial's plot numbers in marker.",anchor={map="WorldStashMap18",note=12}},
{id="t0127-14",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Spray receipt",body="Found it beside two empty chemical tins. Receipt shows both products bought same day. The warning says never mix these formulas.",anchor={map="WorldStashMap18",note=13}},
{id="t0127-15",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Notepad page",body="Notebook sketch: the fourteenth fire burned along the line where yesterday's cordon tape was strung. A patrol truck waited at each end and no one was let past.\n\nNumbered stakes marked the tape every few paces.",anchor={map="WorldStashMap18",note=14}},
{id="t0127-16",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Letter fragment: beneath the fifteenth fire mark I buried a sealed leaf jar. Its leaves spotted black the day after the trial rows were sprayed.\n\nI carried it home because the seed man had no one to return it to. The film from the jar did not come off when I washed my hands.\n\nThe next morning I looked for the second jar and found only the lid. I left this one for whoever tends those rows after me.",anchor={map="WorldStashMap18",note=15}},
{id="t0127-17",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Diary line at the sad face: the field cook wept when three workers could not swallow lunch. All had handled the new grain coating that morning, bare-handed, filling the seed drill.\n\nThe coating came in unmarked sacks from the trial supplier. Nobody had told us to wear gloves.\n\nI wrote down who had touched the sacks, in the order they came to the table, while I still remembered.",anchor={map="WorldStashMap18",note=16}},
{id="t0127-18",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph note",body="The applicator was sick beside his sprayer when I took this. His hands were stained yellow-green to the wrist from the coating. The sample case stayed locked in the cab the whole time.",anchor={map="WorldStashMap18",note=17}},
{id="t0127-19",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Handwritten letter",body="Pay-envelope note at the first happy face: bonus for completing the late spray despite complaints. My hands were numb when I signed.\n\nThe foreman drew the smiling face himself, said it meant we had earned it. Two of the crew had already gone home coughing and still got the same envelope, sealed, no questions.\n\nI have not spent it. It is folded inside this note, and I keep telling myself the numbness is only from the cold mornings.",anchor={map="WorldStashMap18",note=18}},
{id="t0127-20",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Diary page",body="Torn diary page: at the first dead face, a tag with a number stayed tied to the wrist. The posted list later called the wearer an unknown traveler.\n\nI knew him. He ate at our table twice and said he would be sent home by Friday. Nobody who knew his name was asked.\n\nI tore this page out so it would not sit with the ordinary days. The tag number is on the back.",anchor={map="WorldStashMap18",note=19}},
{id="t0127-21",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Sample log page",body="I found the well tender's log by the pasture test site. Water samples smelled sweet like the drums behind the shed. The grass turned grey-green in rings where runoff pooled. Stock refused to drink from the trough after the spraying.",anchor={map="WorldStashMap18",note=20}},
{id="t0127-22",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Photograph note: the third dead face lies beside corn that looks untouched. A trial flag was pulled from the row but its wire hole remains, and the stalks beyond it are sprayed pale at the base.\n\nThe man beside me recognized the planting pattern and went quiet. Only the rows with flags had been treated.\n\nI did not put this back with the ordinary papers.",anchor={map="WorldStashMap18",note=21}},
{id="t0127-23",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Mileage slip back: the fourth dead face was found on the field truck path. Tire tracks lead away before the road closure begins.\n\nI set it aside to show the neighbor when she returned. Her porch was empty by the time the light was good enough to read it.\n\nThe amount mattered to the office more than the people waiting outside. We stayed until dark because the last line still said to wait.",anchor={map="WorldStashMap18",note=22}},
{id="t0127-24",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Diary entry: the fifth dead face is beside the crew wash basin. The water smelled of bleach and sprayer solvent.\n\nThe crew rinsed boots and sprayer hoses here every evening of the trial. I wrote down which hose went with which tank while I could still remember it.\n\nThe water below the basin ran yellow into the ditch.",anchor={map="WorldStashMap18",note=23}},
{id="t0127-25",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Handwritten letter",body="Torn letter: at the sixth dead face, a tarp covered a man still wearing a numbered tag. A tape line ran around him, and someone had chalked a tally beside the tarp.\n\nSomeone wanted a cleaner version of the count. I kept the first one because it shows how many we saw and how many were reported.",anchor={map="WorldStashMap18",note=24}},
{id="t0127-26",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Receipt note: the seventh dead face fell beside feed mixed for the supplement trial. The cart number is absent from the barn account.\n\nThe calves that ate from that cart went off their feed within two days. The mix had a sweet chemical smell the plain feed never had.\n\nI kept the receipt because it names the additive.",anchor={map="WorldStashMap18",note=25}},
{id="t0127-27",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Field note",body="Eight dead crows past the test flags where the wind took the mist. The spray was meant for the plots inside the markers. I found them while checking my own fields downwind.",anchor={map="WorldStashMap18",note=26}},
{id="t0127-28",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Notebook page: a sealed flask beside the ninth dead face contains green field water. The label asks for testing, but no laboratory is named.\n\nI took it from the drainage ditch below the trial plot, where the spray rig was rinsed. The water there had killed the grass along both banks.\n\nI had promised to bring it home for supper. The empty chair at the table and the date on this page now belong to the same evening.",anchor={map="WorldStashMap18",note=27}},
{id="t0127-29",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Photograph",body="Photograph back at the second happy face: the supervisor held up a clean yield sheet while smoke rose behind the trial rows, where the blighted plants were being burned.\n\nSomeone said the smell was only from burning stubble. I kept the scrap because the same sweet smell had come from the last field we treated.\n\nThe stain is where the first yield figure was crossed out. I have not tried to improve it.",anchor={map="WorldStashMap18",note=28}},
{id="t0127-30",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Notebook page",body="Diary margin at the second gun: an armed man collected the roll of names and left the supply invoices. He wore no unit patch.\n\nThe roll was the only list of who had been through the checkpoint. The invoices said only what we had bought.\n\nI wrote this down before the next shift, in the order I saw it, and have not tried to improve it.",anchor={map="WorldStashMap18",note=29}},
{id="t0127-31",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Handwritten letter",body="Letter fragment at the second sad face: twelve calf tags came back from the supplement pasture, but only eleven calves were unloaded.\n\nOur copy stayed on the kitchen table. The official account came later and asked us to remember a much shorter day.\n\nI wanted to keep a clean copy, but the stain is where the first entry was crossed out. I have not tried to improve it.",anchor={map="WorldStashMap18",note=30}},
{id="t0127-32",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Field log at the first skull: this soil core was rejected for a sharp solvent smell. The replacement core came from outside the treated rows.\n\nThe rejected core was grey and dry through the root layer, as if the seedlings had been scalded from below.\n\nI took the page when the lab sent back the replacement and it read clean.",anchor={map="WorldStashMap18",note=31}},
{id="t0127-33",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Receipt back at the second skull: one rain-barrel sample, paid cash. The barrel stood downwind of the experimental orchard.\n\nThe water in it had a film on top that smelled of the spray, and dead bees floated in it.",anchor={map="WorldStashMap18",note=32}},
{id="t0127-34",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Spray Record",body="The mist settled wrong over the back forty yesterday morning. Birds fell mid-flight where the wind carried it thick. Their beaks showed white residue when I checked the rows. I counted eighteen before the rain came.",anchor={map="WorldStashMap18",note=33}},
{id="t0127-35",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Photograph",body="Warehouse note at the fourth skull: the crate count on the dispatch list was nine short of the number loaded onto the truck. The truck had passed two checkpoints.\n\nNo one signed for the nine. The tally was crossed out and rewritten smaller.\n\nI wrote the numbers side by side. The truck was sent back out the same afternoon.",anchor={map="WorldStashMap18",note=34}},
{id="t0127-36",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Farm notebook at the fifth skull: I poured away the milk from the test pasture. The first sick cow came three days after the second spraying.\n\nThe pasture had been sprayed twice that month for the grass trial.\n\nI poured it behind the barn and wrote the dates here.",anchor={map="WorldStashMap18",note=35}},
{id="t0127-37",kind="written",pieces={"letter"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Field notes",body="The spray drifted farther than the wind could carry it. Leaves curled in an hour where the label said three days.\n\nI switched to the backup tank at noon. The same browning appeared on untreated rows by evening.\n\nThe concentrate separated overnight despite constant mixing.",anchor={map="WorldStashMap18",note=36}},
{id="t0127-38",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Diary page",body="Torn ledger at the seventh skull: the final count omits two guards and one supply case. Their truck is still marked returned.\n\nTwo men went to the north cordon and did not come back. The truck stood at the checkpoint with the tailgate open.\n\nI saved the page because their names are on the reverse, and not on the roll.",anchor={map="WorldStashMap18",note=37}},
-- T0128
{id="t0128-01",kind="set",pieces={"Pistol","SeedBag"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Pistol and seed bag",body="I found a pistol and a seed bag together on a shelf. Someone grouped them for a reason. The crops needed both protection and planting.",anchor={map="WorldStashMap19",mark=1}},
-- T0129
{id="t0129-01",kind="set",pieces={"SheetPaper2","Pencil"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Sheet of paper and pencil",body="Found paper listing doors they were turned away from. No names, no dates, only refusals recorded. The pencil scrawled at the end: crew left.",anchor={map="WorldStashMap20",mark=1}},
-- T0130
{id="t0130-01",kind="set",pieces={"SeedBag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="seed bag and water bottle",body="I found a seed bag next to a water bottle. The bag has a chemical smell. The seeds sprouted weird white threads that spread to the bottle.",anchor={map="WorldStashMap21",mark=1}},
{id="t0130-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Orchard diary: at the apple mark, windfalls carried a waxy film after the trial pass. The buyer rejected the whole load as unfit.\n\nThe trees on the treated side had dropped fruit three weeks early. The untreated side held.\n\nI set a few windfalls aside to show the neighbor when she returned. They had split and gone sticky by evening.",anchor={map="WorldStashMap21",mark=2}},
{id="t0130-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Repair receipt: the hammer mark identifies the pump sealed after drawing cloudy field water. Its gasket was new, yet the metal inside had turned green.\n\nThe pump fed the spray tanks for the trial plots. The water in the tank had a sweet, solvent smell.\n\nI wrote the date of the repair here before the pump went back into the line.",anchor={map="WorldStashMap21",mark=3}},
{id="t0130-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Cash slip at the fuel symbol: twelve gallons for the trial sprayer, though its tank holds eight. The clerk wrote the excess under a second farm number.\n\nThe extra four gallons went somewhere else on the trial grounds. The clerk would not say where.\n\nI kept the stained copy because it shows both farm numbers.",anchor={map="WorldStashMap21",note=1}},
{id="t0130-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Field Test Photo",body="The photograph shows spotted fruit beneath clean ones in a crate. A field-trial ribbon marks it as part of the test batch. The same pattern appeared in every orchard using the new spray.",anchor={map="WorldStashMap21",note=2}},
{id="t0130-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Repair note at the hammer symbol: replace the pump gasket after the experimental feed runoff. The old rubber had turned green without cracking.\n\nThe runoff ran from the trial barn into the same ditch the pump draws from. Two gaskets had gone the same way that season.\n\nI wrote the pump number here for the next man to check.",anchor={map="WorldStashMap21",note=3}},
-- T0131
{id="t0131-01",kind="set",pieces={"Hammer","Nails"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Hammer and nails",body="Hammer and nails from a late supply run. Base marked secure days before these even arrived. They signed off on safety before we could board a window.",anchor={map="WorldStashMap22",mark=1}},
-- T0132
{id="t0132-01",kind="set",pieces={"PetrolCan","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Petrol can and notebook",body="The fuel can is tagged for basement storage. The notebook lists a test visit on the same date. Sprayed leaf samples are listed, and the return box is empty.",anchor={map="WorldStashMap23",mark=1}},
{id="t0132-02",kind="written",pieces={"diary"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Diary page",body="Maintenance note: use the hammer mark to find the basement vent. Yellow dust appeared inside after the seed-treatment truck idled above it.\n\nNo one wanted to keep the wet copy. It dried unevenly, and the ink from the first entry stayed visible beneath the second.\n\nI wrote the time before I went back for the others. The clock may have been slow; the second vehicle was already gone.",anchor={map="WorldStashMap23",mark=2}},
{id="t0132-03",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notepad page",body="Cash receipt at the fuel mark: the crop-study truck took two cans but returned one. The driver wrote that the missing can stayed with the basement samples.\n\nThe samples were leaf and soil from the sprayed plots, kept cold. The can was meant to run the pump that kept them so.\n\nI saved the receipt because the driver's name is on the reverse.",anchor={map="WorldStashMap23",note=1}},
{id="t0132-04",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="Fuel receipt headed \"Thunder Gas\": two cans billed to the crop trial. One can returned with a sharp herbal smell and no cap.\n\nThe smell was the same as the spray. The man who filled it said it had been standing in the trial shed.\n\nThe well beside the shed has tasted sweet since. I have stopped using it.",anchor={map="WorldStashMap23",note=2}},
{id="t0132-05",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Photograph",body="Photograph looking back at the boarded vent: they nailed it shut during the evacuation lockdown, day three when the patrol came through. Every access point had to be secured before they'd authorize transport.\n\nThe stored provisions were cleared from the shelves first.\n\nI took the picture before the strip went up.",anchor={map="WorldStashMap23",note=3}},
{id="t0132-06",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook page",body="Diary line under \"basement\": leaf jars from three farms occupied the lower shelf, each labelled with a field name and a date.\n\nThe leaves in each were spotted the same way, black along the veins. Three farms, one treatment.\n\nI copied the dates before the jars were collected.",anchor={map="WorldStashMap23",note=4}},
-- T0133
{id="t0133-01",kind="set",pieces={"Pistol","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pistol and map",body="The map shows a house marked with someone already missing. This pistol was issued days after. They knew but kept going.",anchor={map="WpStashMap1",mark=1}},
-- T0134
{id="t0134-01",kind="set",pieces={"Bandage","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Bandage and notebook",body="The bandage smells like chemicals, not antiseptic. The notebook lists crop treatments alongside medical symptoms. Yellow residue stains both the pages and the wrapping.",anchor={map="WpStashMap2",mark=1}},
-- T0135
{id="t0135-01",kind="set",pieces={"Antibiotics","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Antibiotics and map",body="A broken barrier board crushed the antibiotics against the map. Clean undersides suggest both were there before the road was blocked.",anchor={map="WpStashMap3",mark=1}},
-- T0136
{id="t0136-01",kind="set",pieces={"SeedBag","LetterHandwritten"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Seed bag and letter",body="A seed packet is wrapped in a loving note. It asks the reader to avoid the workroom until the next test is over. The return time is blank.",anchor={map="WpStashMap4",mark=1}},
-- T0137
{id="t0137-01",kind="set",pieces={"Shotgun","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Shotgun and paper sheet",body="The shotgun's logged on the paper sheet. Transfer was signed before they checked this place. Can't find who was supposed to hold it.",anchor={map="WpStashMap11",mark=1}},
-- T0138
{id="t0138-01",kind="set",pieces={"Screwdriver","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="screwdriver and notebook",body="I found a screwdriver on top of a notebook. The page lists crop sectors and application schedules. Someone wrote 'dilution ratio wrong?' in the margin.",anchor={map="WpStashMap5",mark=1}},
-- T0139
{id="t0139-01",kind="set",pieces={"WaterBottle","Bag_ALICEpack"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Water bottle and pack",body="The alicepack is buckled shut, water bottle clipped on the side. A departure slip is tucked in the webbing. Time written in, but no signature on the authorization line.",anchor={map="WpStashMap6",mark=1}},
-- T0140
{id="t0140-01",kind="set",pieces={"Notebook","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook and pencil",body="The notebook is open to a blank plot line, a pencil across it. The sprayer and nozzles were checked out and not signed back. The tank still has residue in it.",anchor={map="WpStashMap7",mark=1}},
-- T0141
{id="t0141-01",kind="set",pieces={"AnimalFeedBag","WalkieTalkie1"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Feed sack and radio",body="The radio's locked on emergency dispatch. This feed sack has stamps for three evacuation sites. Someone crossed two out and never told the convoy crews.",anchor={map="WpStashMap8",mark=1}},
-- T0142
{id="t0142-01",kind="set",pieces={"WaterBottle","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Water bottle and notebook",body="The bottle was rationed to a household. The notebook says the path was too hot after treatment. I see the crew's application dates.",anchor={map="WpStashMap9",mark=1}},
-- T0143
{id="t0143-01",kind="set",pieces={"Calculator","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Calculator and first-aid kit",body="The calculator is tied to the first-aid kit by a clipped lanyard. An empty loop looks like where an identifying tag was cut off.",anchor={map="WpStashMap10",mark=1}},
-- T0144
{id="t0144-01",kind="set",pieces={"MeasuringTape","Clipboard"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Measuring tape and clipboard",body="The measuring tape and clipboard have the same black paint. A fresh scrape shows an older evacuation color underneath.",anchor={map="WpStashMap12",mark=1}},
-- T0145
{id="t0145-01",kind="set",pieces={"BaseballBat","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Baseball bat and paper sheet",body="This paper lists weapons given out, including the bat. Column for who came back is empty. One entry repeats.",anchor={map="WpStashMap13",mark=1}},
-- T0146
{id="t0146-01",kind="set",pieces={"Bread","Map"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Bread and map",body="The bread was rationed for the wait. The map shows the spray zones marked in red. Someone drew a boat route avoiding those fields.",anchor={map="WpStashMap14",mark=1}},
-- T0147
{id="t0147-01",kind="set",pieces={"Comb","HandTorch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Comb and hand torch",body="Road dust coats the comb and the torch. The ties are clean and newly cut. I think the bundle was repacked after travel.",anchor={map="WpStashMap15",mark=1}},
-- T0148
{id="t0148-01",kind="set",pieces={"Map","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Map and pencil",body="The map marks a fence and a southbound exit route. A pencil note ties the attack path to the last field spraying.",anchor={map="WpStashMap16",mark=1}},
-- T0150
{id="t0150-01",kind="set",pieces={"Axe","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Axe and paper sheet",body="The paper sheet says to pull back from the checkpoint. Their axe lies beside the barrier, half-cleared. Someone still billed full hours.",anchor={print="McCoyLoggingCorp"}},
-- T0151
{id="t0151-01",kind="set",pieces={"Toothbrush","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Toothbrush and bath towel",body="The toothbrush and bath towel are wedged under unused warning tape. Footprints go around the bundle, not toward it.",anchor={print="NolansUsedCars"}},
-- T0152
{id="t0152-01",kind="set",pieces={"WaterBottle","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Water bottle and paper sheet",body="The paper sheet closes this route before dawn for pickups. The water bottle here was issued hours after that deadline.",anchor={print="WestMapleCountryClub"}},
{id="t0152-02",kind="set",pieces={"Pencil","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Pencil and notebook",body="The notebook has pencil entries tracking spray applications. Chemical amounts listed for each field section. Final entry: triple dose, circled and underlined.",anchor={print="WestMapleCountryClub"}},
-- T0153
{id="t0153-01",kind="set",pieces={"Scissors","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Scissors and paper sheet",body="The paper sheet is stamped complete before the pickup time. It says leave the back door open for the return van. Scissors beside it, like they were rushing people through.",anchor={print="FashionaBelle"}},
-- T0154
{id="t0154-01",kind="set",pieces={"EmptyJar","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Empty jar and pencil",body="The pencil marked doses for the new growth accelerator trial. The empty jar beside it has crystallized residue inside. The numbers were doubled partway through the season.",anchor={print="TacodelPancho"}},
-- T0155
{id="t0155-01",kind="set",pieces={"Wallet","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Wallet and map",body="I found a map in the wallet with some official paperwork. Says the checkpoint was cleared at noon. The buses weren't scheduled until two.",anchor={print="CrossRoadsMall"}},
-- T0156
{id="t0156-01",kind="set",pieces={"Toothpaste","Camera"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Toothpaste and camera",body="Four notches on the toothpaste match four marks on the camera. A fifth mark was sanded flat on both.",anchor={print="UStoreItRiverside"}},
-- T0157
{id="t0157-01",kind="set",pieces={"Mirror","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Mirror and briefcase",body="The hand mirror and briefcase are bound with a torn sleeve. The fabric is smoke-stained outside and spotless beneath the knot.",anchor={print="UStoreItLouisville"}},
-- T0158
{id="t0158-01",kind="set",pieces={"SeedBag","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Seed bag and water bottle",body="A seed bag is listed for a rented unit. The note says keep the water sealed until the field reading is back.",anchor={print="UStoreItMuldraugh"}},
-- T0159
{id="t0159-01",kind="set",pieces={"Badge","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Badge and map",body="Opposite route arrows are painted on the badge and the folded map. The older arrow was scraped away under fresh road grit.",anchor={print="Fossoil1"}},
-- T0160
{id="t0160-01",kind="set",pieces={"PetrolCan","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Petrol can and paper sheet",body="A fuel sheet logs a sample taken before the pump opened to customers. The cashier's shift starts after the sample is marked cleared.",anchor={print="Fossoil2"}},
-- T0161
{id="t0161-01",kind="set",pieces={"DuctTape","WalkieTalkie1"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Duct tape and hand radio",body="The duct tape and radio were sealed together, never opened. Soot darkens the bundle. The clean outlines suggest it was packed before the fire.",anchor={print="Fossoil3"}},
-- T0162
{id="t0162-01",kind="set",pieces={"PetrolCan","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Petrol can and notebook",body="A petrol can sits with a notebook. The entry says the spray test was routine. Then it tells the next shift not to use this can again.",anchor={print="Fossoil4"}},
-- T0163
{id="t0163-01",kind="set",pieces={"Whistle","FirstAidKit"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Whistle and first-aid kit",body="Matching white stripes cross the whistle and the first-aid kit. A name-sized patch on the whistle has been scrubbed bare.",anchor={print="Fossoil5"}},
-- T0164
{id="t0164-01",kind="set",pieces={"PetrolCan","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Petrol can and pencil",body="The petrol can has a tag for the sprayer route. Someone penciled in the fuel level at full. The can's barely a quarter now.",anchor={print="Fossoil6"}},
-- T0165
{id="t0165-01",kind="set",pieces={"Map","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Map and paper sheet",body="The map shows this route already closed. The paper sheet orders a driver to wait at the fuel pump. The pickup never came.",anchor={print="Fossoil7"}},
-- T0166
{id="t0166-01",kind="set",pieces={"Rope","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="rope and water bottle",body="The rope reeks of pesticide concentrate. Yellow chemical stains ring the water bottle. Both lay beside a split fertilizer bag.",anchor={print="Fossoil8"}},
-- T0167
{id="t0167-01",kind="set",pieces={"Map","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Map and water bottle",body="The map marks the area clear before they got anyone out. The water bottle's from a supply count closed too soon.",anchor={print="Delilah"}},
-- T0168
{id="t0168-01",kind="set",pieces={"FishingRod","HandTorch"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Fishing rod and hand torch",body="A fishing rod and hand torch left by the water. They said not to fish until the runoff test clears. The upstream field was sprayed yesterday.",anchor={print="BensCabin"}},
-- T0169
{id="t0169-01",kind="set",pieces={"Map","Wallet"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Map and wallet",body="The map shows downtown, every block marked evacuated. The wallet has a receipt from two hours after the sweep. Someone was still shopping when they called it clear.",anchor={print="GrandOhioMall"}},
-- T0170
{id="t0170-01",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Receipt",body="A feed-store receipt lists fuel and rinse soap beside a handwritten line: \"Trial rig at the track before sunrise. Wash the tank before the first cars arrive.\"\n\nThe soap was bought by the case, enough for a sprayer tank many times over. The rig left a yellow ring on the gravel.\n\nI kept the page because the handwriting is the trial foreman's.",anchor={print="DragRacingTrack"}},
-- T0171
{id="t0171-01",kind="set",pieces={"Twine","HandTorch"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Twine and hand torch",body="Red and blue cord join the baling twine to the torch. The red route is cut. The blue route ends in a sealed knot.",anchor={print="ArtGalleryofLouisville"}},
-- T0172
{id="t0172-01",kind="set",pieces={"BaseballBat","WaterBottle"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Baseball bat and water bottle",body="A water bottle lies beside a bat. The gate log says lock up early. The schedule still shows tonight's game open to fans.",anchor={print="FossoilField"}},
-- T0173
{id="t0173-01",kind="set",pieces={"Crayons","BathTowel"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Crayons and bath towel",body="Chalk numbers run across the crayons and the bath towel. The count skips one place, then resumes in a different hand.",anchor={print="SunstarMotel"}},
-- T0174
{id="t0174-01",kind="set",pieces={"WaterBottle","Notebook"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Water bottle and notebook",body="The notebook has lockdown orders, one line per floor, all checked. One floor shows no count, just a stamp marking it complete. The water bottle beside it was left unopened.",anchor={print="HavishamSuites"}},
-- T0175
{id="t0175-01",kind="set",pieces={"BaseballBat","SheetPaper2"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Baseball bat and paper sheet",body="A bat sits with a production sheet listing units made. The line for units handed to the evacuation convoy is inked out. The clerk's initials are left beside it.",anchor={print="LouisvilleBruiser"}},
-- T0176
{id="t0176-01",kind="set",pieces={"FishFillet","KitchenKnife"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Fish fillet and kitchen knife",body="Names are carved into the kitchen knife handle. One is scratched through. The fish fillet is from official evacuation rations.",anchor={print="TheSeaShanty"}},
-- T0177
{id="t0177-01",kind="set",pieces={"Wine","EmptyJar"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Wine and empty jar",body="A manifest lists twelve wine bottles but I count only eleven. An empty jar bears a quarantine tag crossed out in black ink. The evacuation roster for that week has its last page missing.",anchor={print="ScarletOakDistillery"}},
-- T0178
{id="t0178-01",kind="set",pieces={"Bag_ALICEpack","Map"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Pack and map",body="I found a pack with a map showing checkpoint routes. Map notes say patrol use only, do not share with civilians. They left it behind at the first stop.",anchor={print="ReadyPrep"}},
-- T0179
