{id="t0179-02",kind="set",pieces={"Notebook","Pencil"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Notebook and pencil",body="The notebook marks test strips along the spraying pathway. The pencil underlines a warning to avoid the drainage ditch.",anchor={print="WellingtonHeightsGolfClub"}},
-- T0180
{id="t0180-01",kind="set",pieces={"Crowbar","Briefcase"},where={{place="mapNamed",spot="furniture",lean="containment",rival="agricultural"}},title="Crowbar and briefcase",body="A broken barrier board crushed the crowbar against the briefcase. Clean undersides suggest both were there before the road was blocked.",anchor={print="LSU"}},
-- T0181
{id="t0181-01",kind="set",pieces={"Screwdriver","Notebook"},where={{place="mapNamed",spot="furniture",lean="agricultural",rival="containment"}},title="Screwdriver and notebook",body="The notebook's job sheet puts the operator on the seed-coating run. The screwdriver was logged back in with coating dried on the grips.",anchor={print="LectromaxManufacturingJobAd"}},
-- T0182
